verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const rd=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return null}}
const code=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
// Drop IMPORT lines before looking for a CALL. A surviving import kept three arms of the first
// draft of this probe green while the call was gone, which is the trap LIVE-518 and LIVE-421 both
// hit. Word-bounded regexes below for the same class of reason: SearchSunLongitudeX contains
// SearchSunLongitude, so indexOf would pass on a renamed-away symbol.
const body=(s)=>code(s).replace(/^\s*import[\s\S]*?from\s+.*$/gm," ")

const A=rd("lib/calendar/astro-markers.ts")
if(A===null)fail("the sky marker module is gone")
const ac=code(A)
if(/SearchMoonPhase/.test(ac))fail("the moons are being computed here a second time: lib/calendar/moon.ts already solves them and is what vera-calendar hands a model, so two engines are free to disagree")
const ab=body(A)
if(!/\blunarPhaseInstants\s*\(\s*phase/.test(ab))fail("the moons no longer CALL lib/calendar/moon.ts (an import left behind is not a call), so they are either gone or computed here a second time")
if(!/\bSearchSunLongitude\s*\(/.test(ab))fail("the sign ingresses are gone, so no equinox, solstice or zodiac day is computed at all")
if(/\bdefault\s*:/.test(ac))fail("the marker switch grew a default arm")
if(/label:[^\n]*season/i.test(ac))fail("a marker LABEL is using the word season, which docs/NAMING.md locks for the Quest (a Quest IS a season) and this copy is member-facing")
if(ac.indexOf("Sun enters ")<0)fail("the ingress label is no longer the standard phrasing the owner ruled on")

const S=rd("lib/spaces/sky-markers.ts")
if(S===null)fail("the per-Space opt-in accessor is gone")
const sc=code(S)
if(!/=== true/.test(sc))fail("the opt-in no longer requires a real true, so a stored string could switch a public surface on")
if(sc.indexOf("delete prefs.skyMarkers")<0)fail("the writer stopped deleting the key when turned off, so an untouched Space no longer keeps a clean blob")

const P=rd("app/(main)/spaces/[slug]/(profile)/calendar/page.tsx")
if(P===null)fail("the Space calendar page is gone")
const pc=code(P)
const pb=body(P)
if(!/\breadSkyMarkersEnabled\s*\(/.test(pb))fail("the calendar page stopped reading the opt-in, so every Space would get the sky whether it asked or not")
if(!/\bastroMarkersInRange\s*\(/.test(pb))fail("the calendar page no longer computes the markers")
if(!/\bwidenDayRange\s*\(/.test(pb))fail("the server window is no longer widened past the opening month, so browsing to the next month shows an empty sky")
const mounts=(pc.match(/skyMarkers=\{skyMarkers\}/g)||[]).length
if(mounts<1)fail("the public tab no longer hands the sky markers to its CalendarWorkspace, so the visitor sees nothing")

const W=rd("components/spaces/calendar-workspace.tsx")
if(W===null)fail("the calendar workspace is gone")
const wc=code(W)
if((wc.match(/skyMarkers=\{skyMarkers\}/g)||[]).length<2)fail("the workspace hands the sky to only one grid: passing it to the staff grid alone is the LIVE-478 failure shape, where the marker is in the file and the audience that needs it sees nothing")

const G=rd("components/events/event-calendar.tsx")
if(G===null)fail("the calendar grid is gone")
const gc=code(G)
if(gc.indexOf("data-sky-marker")<0)fail("the grid draws no sky marker")
if(!/import type \{ AstroMarker/.test(G))fail("the grid imports the marker module for REAL rather than as a type: astronomy-engine is 116 KB minified in the browser build and this file is a client component, so that ships the ephemeris to every phone")
const T=rd("components/events/event-calendar.sky.render.test.tsx")
if(T===null)fail("the guest-mount render test is gone: without it nothing proves a MEMBER sees the marker, only that the prop exists")
if(T.indexOf("data-day-cell")<0)fail("the render test stopped reading the real day cell")
console.log("LIVE-526 ok")'
